<?php
session_start();
if (empty($_SESSION['admin_ok'])) { header('Location: admin.php'); exit; }
if (($_SESSION['admin_role'] ?? 'user') !== 'admin') { http_response_code(403); exit('Acesso permitido somente para administradores.'); }
function e($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function loadQuotes($f){ $a=is_file($f)?json_decode((string)file_get_contents($f),true):[]; return is_array($a)?$a:[]; }
function saveQuotes($f,$a){ return file_put_contents($f,json_encode(array_values($a),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX)!==false; }
function quoteTotal($q){ $t=0; foreach(($q['items']??[]) as $i) if(is_numeric($i['price']??null)) $t+=(float)$i['price']*max(1,(int)($i['qty']??1)); return $t*(1-max(0,min(100,(float)($q['discount']??0)))/100); }
function dbr($v){ if(!$v)return '—'; $t=strtotime($v); return $t?date('d/m/Y',$t):'—'; }
$labels=['rascunho'=>'Rascunho','enviado'=>'Enviado','negociacao'=>'Em negociação','aprovado'=>'Aprovado','perdido'=>'Perdido','cancelado'=>'Cancelado'];
$file=__DIR__.'/data/orcamentos.json'; $all=loadQuotes($file); $admin=(string)($_SESSION['admin_user']??'admin');
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='status'){
    $id=(string)($_POST['id']??''); $new=(string)($_POST['status']??'');
    if(!isset($labels[$new])) $new='rascunho';
    foreach($all as &$q){ if(($q['id']??'')!==$id) continue; $old=(string)($q['status']??'rascunho'); if($old!==$new){ $q['status']=$new; $q['updated_at']=date('c'); if(!isset($q['history'])||!is_array($q['history']))$q['history']=[]; $q['history'][]=['at'=>date('c'),'user'=>$admin,'event'=>'status','from'=>$old,'to'=>$new,'by_admin'=>true]; } break; } unset($q);
    saveQuotes($file,$all); $back='gestao_orcamentos.php'; $qs=trim((string)($_POST['return_query']??'')); if($qs!=='')$back.='?'.$qs; header('Location: '.$back); exit;
}
$search=mb_strtolower(trim((string)($_GET['busca']??'')),'UTF-8'); $status=trim((string)($_GET['status']??'')); $consultor=trim((string)($_GET['consultor']??'')); $inicio=trim((string)($_GET['inicio']??'')); $fim=trim((string)($_GET['fim']??''));
$consultores=[]; foreach($all as $q){$u=trim((string)($q['user']??''));if($u!==''&&!in_array($u,$consultores,true))$consultores[]=$u;} natcasesort($consultores); $consultores=array_values($consultores);
$quotes=array_values(array_filter($all,function($q)use($search,$status,$consultor,$inicio,$fim){
    if($status!=='' && ($q['status']??'rascunho')!==$status)return false;
    if($consultor!=='' && strcasecmp((string)($q['user']??''),$consultor)!==0)return false;
    $dt=substr((string)($q['created_at']??$q['updated_at']??''),0,10); if($inicio!==''&&$dt!==''&&$dt<$inicio)return false; if($fim!==''&&$dt!==''&&$dt>$fim)return false;
    if($search!==''){ $c=$q['customer']??[]; $hay=mb_strtolower(implode(' ',[(string)($q['number']??$q['id']??''),(string)($q['user']??''),(string)($c['name']??$q['note']??''),(string)($c['vehicle']??''),(string)($c['plate']??''),(string)($c['phone']??''),(string)($c['document']??'')]),'UTF-8'); if(!str_contains($hay,$search))return false; }
    return true;
}));
usort($quotes,fn($a,$b)=>strcmp((string)($b['updated_at']??$b['created_at']??''),(string)($a['updated_at']??$a['created_at']??'')));
$totalValor=0;$aprovados=0;$negociacao=0;$perdidos=0;foreach($quotes as$q){$totalValor+=quoteTotal($q);$s=$q['status']??'rascunho';if($s==='aprovado')$aprovados++;if($s==='negociacao')$negociacao++;if($s==='perdido')$perdidos++;}
$baseConversao=$aprovados+$perdidos;$conversao=$baseConversao?($aprovados/$baseConversao*100):0;
$byUser=[];foreach($quotes as$q){$u=(string)($q['user']??'Sem usuário');if(!isset($byUser[$u]))$byUser[$u]=['n'=>0,'valor'=>0,'aprovados'=>0,'negociacao'=>0,'perdidos'=>0];$byUser[$u]['n']++;$byUser[$u]['valor']+=quoteTotal($q);$s=$q['status']??'rascunho';if(isset($byUser[$u][$s.'s']))$byUser[$u][$s.'s']++;elseif($s==='negociacao')$byUser[$u]['negociacao']++;}
$view=null;$viewId=(string)($_GET['ver']??'');if($viewId!=='')foreach($all as$q)if(($q['id']??'')===$viewId){$view=$q;break;}
$return=$_GET;unset($return['ver']);$returnQuery=http_build_query($return);
