.crm-admin-cards{display:grid;grid-template-columns:repeat(5,minmax(150px,1fr));gap:14px;margin:0 0 20px}.crm-admin-card{background:#fff;border:1px solid #dbe5ef;border-radius:14px;padding:18px}.crm-admin-card small{display:block;color:#61758a;margin-bottom:7px}.crm-admin-card strong{font-size:1.45rem;color:#09243a}.crm-filter-wide{display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr auto auto;gap:10px;align-items:end}.crm-filter-wide label{font-size:12px;font-weight:700;color:#52677b}.crm-filter-wide input,.crm-filter-wide select{width:100%;margin-top:4px}.crm-detail{margin-bottom:20px}.crm-detail-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.crm-detail-box{background:#f6f9fc;border:1px solid #dbe5ef;border-radius:10px;padding:12px}.crm-detail-box b{display:block;margin-bottom:4px}.crm-status-form{display:flex;gap:7px;align-items:center}.crm-status-form select{min-width:145px}.crm-summary{margin-top:20px}@media(max-width:1000px){.crm-admin-cards{grid-template-columns:repeat(2,1fr)}.crm-filter-wide{grid-template-columns:1fr 1fr}.crm-detail-grid{grid-template-columns:1fr}}@media(max-width:600px){.crm-admin-cards,.crm-filter-wide{grid-template-columns:1fr}}
</style></head><body class="admin-page"><header class="admin-header"><div class="container admin-header-inner"><a href="index.php" class="logo logo-image"><img src="assets/eleds-logo.png" alt="HE"></a><div class="admin-actions"><a href="admin.php">Administração</a><a href="orcamentos.php">Meus orçamentos</a><a href="index.php">Catálogo</a><a href="admin.php?logout=1">Sair</a></div></div></header><main class="container admin-main"><div class="admin-title"><div><span class="section-kicker">ADMINISTRADOR</span><h1>Gestão de Orçamentos</h1><p>Consulte e acompanhe os orçamentos de todos os consultores.</p></div><a class="admin-primary" href="index.php">+ Novo orçamento</a></div>
<div class="crm-admin-cards"><div class="crm-admin-card"><small>Orçamentos encontrados</small><strong><?=count($quotes)?></strong></div><div class="crm-admin-card"><small>Valor orçado</small><strong>R$ <?=number_format($totalValor,2,',','.')?></strong></div><div class="crm-admin-card"><small>Aprovados</small><strong><?=$aprovados?></strong></div><div class="crm-admin-card"><small>Em negociação</small><strong><?=$negociacao?></strong></div><div class="crm-admin-card"><small>Conversão*</small><strong><?=number_format($conversao,1,',','.')?>%</strong></div></div>
<?php if($view):$c=$view['customer']??[];$com=$view['commercial']??[];?><section class="admin-panel crm-detail"><div class="admin-list-head"><h2><?=e($view['number']??$view['id'])?> — Detalhes</h2><a href="gestao_orcamentos.php<?=$returnQuery?'?'.e($returnQuery):''?>">Fechar</a></div><div class="crm-detail-grid"><div class="crm-detail-box"><b>Consultor</b><?=e($view['user']??'—')?></div><div class="crm-detail-box"><b>Cliente</b><?=e($c['name']??$view['note']??'—')?></div><div class="crm-detail-box"><b>Contato</b><?=e($c['phone']??'—')?><?=!empty($c['email'])?' · '.e($c['email']):''?></div><div class="crm-detail-box"><b>Veículo</b><?=e($c['vehicle']??'—')?><?=!empty($c['plate'])?' · '.e(strtoupper($c['plate'])):''?></div><div class="crm-detail-box"><b>Condição</b><?=e($com['payment']??'—')?></div><div class="crm-detail-box"><b>Retorno</b><?=dbr($com['return_date']??'')?></div></div><div class="admin-table-wrap" style="margin-top:14px"><table class="admin-table"><thead><tr><th>Código</th><th>Produto</th><th>Qtd.</th><th>Unitário</th><th>Subtotal</th></tr></thead><tbody><?php foreach(($view['items']??[])as$i):$p=$i['price']??null;?><tr><td><?=e($i['code']??'')?></td><td><?=e($i['name']??'')?></td><td><?=intval($i['qty']??1)?></td><td><?=$p===null?'—':'R$ '.number_format((float)$p,2,',','.')?></td><td><?=$p===null?'—':'R$ '.number_format((float)$p*max(1,(int)($i['qty']??1)),2,',','.')?></td></tr><?php endforeach;?></tbody></table></div><p><strong>Desconto:</strong> <?=number_format((float)($view['discount']??0),2,',','.')?>% &nbsp; <strong>Total:</strong> R$ <?=number_format(quoteTotal($view),2,',','.')?> &nbsp; <strong>Validade:</strong> <?=intval($com['validity']??7)?> dia(s)</p><?php if(!empty($view['note'])):?><p><strong>Observações:</strong> <?=nl2br(e($view['note']))?></p><?php endif;?></section><?php endif;?>
<section class="admin-panel"><form method="get" class="crm-filter-wide"><label>Pesquisar<input name="busca" value="<?=e($_GET['busca']??'')?>" placeholder="Nº, cliente, placa, veículo ou consultor"></label><label>Situação<select name="status"><option value="">Todas</option><?php foreach($labels as$k=>$v):?><option value="<?=e($k)?>" <?=$status===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><label>Consultor<select name="consultor"><option value="">Todos</option><?php foreach($consultores as$u):?><option value="<?=e($u)?>" <?=strcasecmp($consultor,$u)===0?'selected':''?>><?=e($u)?></option><?php endforeach;?></select></label><label>De<input type="date" name="inicio" value="<?=e($inicio)?>"></label><label>Até<input type="date" name="fim" value="<?=e($fim)?>"></label><button class="admin-primary">Pesquisar</button><a href="gestao_orcamentos.php">Limpar</a></form><div class="admin-table-wrap" style="margin-top:18px"><table class="admin-table"><thead><tr><th>Orçamento</th><th>Consultor</th><th>Cliente / veículo</th><th>Situação</th><th>Valor</th><th>Data / retorno</th><th>Ações</th></tr></thead><tbody><?php if(!$quotes):?><tr><td colspan="7">Nenhum orçamento encontrado.</td></tr><?php endif;?><?php foreach($quotes as$q):$c=$q['customer']??[];$s=$q['status']??'rascunho';?><tr><td><strong><?=e($q['number']??$q['id'])?></strong></td><td><?=e($q['user']??'—')?></td><td><strong><?=e($c['name']??$q['note']??'Sem identificação')?></strong><br><small><?=e($c['vehicle']??'')?><?=!empty($c['plate'])?' · '.e(strtoupper($c['plate'])):''?></small></td><td><span class="crm-status s-<?=e($s)?>"><?=e($labels[$s]??'Rascunho')?></span></td><td><strong>R$ <?=number_format(quoteTotal($q),2,',','.')?></strong></td><td><?=dbr($q['created_at']??'')?><?php if(!empty($q['commercial']['return_date'])):?><br><small>Retorno: <?=dbr($q['commercial']['return_date'])?></small><?php endif;?></td><td class="admin-row-actions"><a href="?<?=e(http_build_query(array_merge($_GET,['ver'=>$q['id']])))?>">Ver</a><form method="post" class="crm-status-form"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=e($q['id'])?>"><input type="hidden" name="return_query" value="<?=e($returnQuery)?>"><select name="status"><?php foreach($labels as$k=>$v):?><option value="<?=e($k)?>" <?=$s===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select><button type="submit">Atualizar</button></form></td></tr><?php endforeach;?></tbody></table></div><p style="margin-top:12px;color:#61758a;font-size:13px">* Conversão = aprovados ÷ (aprovados + perdidos), considerando os filtros selecionados.</p></section>
<?php if($byUser):?><section class="admin-panel crm-summary"><h2>Resumo por consultor</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Consultor</th><th>Orçamentos</th><th>Valor orçado</th><th>Aprovados</th><th>Em negociação</th><th>Perdidos</th></tr></thead><tbody><?php foreach($byUser as$u=>$r):?><tr><td><strong><?=e($u)?></strong></td><td><?=$r['n']?></td><td>R$ <?=number_format($r['valor'],2,',','.')?></td><td><?=$r['aprovados']?></td><td><?=$r['negociacao']?></td><td><?=$r['perdidos']?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></main></body></html>
